function main({from="-1d@d", to="@d"}) {
    setEnv("from", from)
    setEnv("to", to)
    let data_ingress = Platform_Metric_Query(Platform_Metric_QueryBuild(queryOptions("platform_egress_bytes", from, to)), to)
    let count_ingress = Platform_Metric_Query(Platform_Metric_QueryBuild(queryOptions("platform_egress_count", from, to)), to)

    return {data_ingress, count_ingress}
}

function queryOptions(metric, timeFrom, timeTo) {
    let timeFrom = new Time(timeFrom)
    let timeTo = new Time(timeTo)
    let days = (timeTo.Unix() - timeFrom.Unix()) / 86400
    return {
        metric: metric,
        select: "",
        duration: `${days}d`,
        stat: "increase",
        aggregate:"sum",
        groupBy: []
    }
}
